-- VR, which the importer dropped. IGDB lists VR games on their headsets
-- (Meta Quest, PlayStation VR2, SteamVR and the rest), and none of those
-- were mapped, so a game only on a headset showed no platforms at all. This
-- adds Meta Quest as a platform of its own, since it is a machine you play
-- on with nothing else to fold into, and puts every other headset with the
-- machine it runs from: PlayStation VR2 a PS5, PlayStation VR a PS4, SteamVR
-- Steam, and Rift and Windows Mixed Reality a PC. The catalogue is filled
-- from IGDB's own lists as of 2026-11-17. It only adds; nothing is taken
-- away, and logs are left as they are.

set search_path = pg_catalog, public;

insert into public.platforms (slug, display_name, sort_order)
values ('meta-quest', 'Meta Quest', 65)
on conflict (slug) do nothing;

insert into public.platform_systems (slug, display_name, platform_slug, sort_order)
values ('meta-quest', 'Meta Quest', 'meta-quest', 6510)
on conflict (slug) do nothing;

create temporary table vr_games (igdb_id bigint, system_slug text, platform_slug text);

-- Quest, Quest 2, Quest 3, Go and Gear VR (IGDB 384, 386, 471, 387, 388).
insert into vr_games (igdb_id, system_slug, platform_slug)
