insert into public.game_systems (game_id, system_slug)
select g.id, v.system_slug
from vr_games v
join public.games g on g.igdb_id = v.igdb_id
on conflict do nothing;

insert into public.game_platforms (game_id, platform_slug)
select g.id, v.platform_slug
from vr_games v
join public.games g on g.igdb_id = v.igdb_id
on conflict do nothing;

drop table vr_games;
